local config = {
  ui_story_5025_50253301_1_dialog_content = "Menemukan semua yang Anda cari?",
  ui_story_5025_50253301_2_dialog_content = "Tunggu. Satu hal lagi... buku catatan.",
  ui_story_5025_50253301_3_dialog_content = "Aku butuh buku catatan. Yang tebal.",
  ui_story_5025_50253301_4_dialog_content = "Oh? Saya kira remaja memiliki banyak hal yang ingin mereka curahkan melalui tulisan.",
  ui_story_5025_50253301_5_dialog_content = "Tidak, itu bukan untukku. Ini hadiah untuk Vice.",
  ui_story_5025_50253301_6_dialog_content = "Oh, ya? Buku catatan untuk dia... Rupanya hubungan kalian lebih dekat ketimbang dugaanku.",
  ui_story_5025_50253301_7_dialog_content = "J-Jangan mempermasalahkan ini! Saya kebetulan melihat bahwa buku catatan Vice hampir penuh...",
  ui_story_5025_50253301_8_dialog_content = "Wah, tinggal tersisa beberapa halaman saja... Waktu berlalu dengan cepat, ya...",
  ui_story_5025_50253301_9_dialog_content = "Apa yang harus saya tulis?",
