  ui_story_5025_50253301_11_dialog_content = "Mungkin sebaiknya aku mengakhirinya dengan...",
  ui_story_5025_50253301_12_dialog_content = "Vice, kau bergumam apa, sih?",
  ui_story_5025_50253301_13_dialog_content = "Hah? PlayerName, sudah berapa lama kau di situ?",
  ui_story_5025_50253301_14_dialog_content = "Ehem, tidak lama... Jangan khawatir. Saya tidak mendengar apa pun yang seharusnya tidak saya dengar.",
  ui_story_5025_50253301_15_dialog_content = "Saya hanya ingin tahu bagaimana Anda berencana untuk mengakhiri buku harian itu.",
  ui_story_5025_50253301_16_dialog_content = "Hmm... Soalnya, saya baru sadar jurnal perjalanan dan petualangan saya hampir habis.",
  ui_story_5025_50253301_17_dialog_content = "Aku bingung mau menulis apa untuk entri terakhirnya...",
  ui_story_5025_50253301_18_option_content = "Aku sangat penasaran apa yang akan kau tulis...",
  ui_story_5025_50253301_19_dialog_content = "Heheh. Mau membacanya?",
  ui_story_5025_50253301_20_dialog_content = "Boleh saja... Memangnya apanya yang lucu?",
  ui_story_5025_50253301_21_dialog_content = "Aku tidak memberitahumu! Semua yang ada di buku catatan itu rahasia.",
  ui_story_5025_50253301_22_dialog_content = "Baiklah, kau tidak perlu memberitahuku. Tapi kenapa kau tersenyum begitu gugup?",
  ui_story_5025_50253301_23_dialog_content = "Apakah Anda menulis sesuatu yang buruk tentang saya?",
  ui_story_5025_50253301_24_dialog_content = "Tidak, tak pernah! Aku... hmm... aku tak bisa memberitahumu sekarang.",
  ui_story_5025_50253301_25_option_content = "Baiklah, aku tak akan memaksa, kok.",
  ui_story_5025_50253301_26_dialog_content = "Meskipun saya benar-benar ingin tahu apa yang Anda rencanakan untuk ditulis.",
  ui_story_5025_50253301_27_dialog_content = "Tapi, rasanya kok tidak pantas ya kalau membaca buku harianmu. Yang semacam itu kan cukup personal.",
  ui_story_5025_50253301_28_dialog_content = "Maksudku, aku tidak keberatan membiarkanmu membacanya jika kau mau...",
  ui_story_5025_50253301_29_dialog_content = "Hmm? Mengapa demikian? Anda tidak keberatan orang lain mengorek privasi Anda?",
  ui_story_5025_50253301_30_dialog_content = "Itu hanya... Ya, kami berteman baik!",
  ui_story_5025_50253301_31_dialog_content = "Ehem... Cukup sudah. Kenapa kamu di sini begitu larut malam?",
  ui_story_5025_50253301_32_dialog_content = "Saya ingin mendiskusikan perjalanan belanja kami dalam beberapa hari.",
  ui_story_5025_50253301_33_dialog_content = "Ah, itu. Jangan khawatir. Saya akan menulis daftar untuk Anda.",
  ui_story_5025_50253301_34_dialog_content = "Beli saja semua yang ada di daftar.",
  ui_story_5025_50253301_35_dialog_content = "Sepertinya Vice suka menulis di buku harian.",
  ui_story_5025_50253301_36_dialog_content = "Jadi saya ingin memberinya buku catatan. Hanya sebagai kejutan kecil.",
  ui_story_5025_50253301_37_dialog_content = "Dia telah bersamaku untuk beberapa waktu sekarang... Itu cara yang bagus untuk menunjukkan penghargaanku.",
  ui_story_5025_50253301_38_dialog_content = "Hmm... Begitu rupanya...",
  ui_story_5025_50253301_39_dialog_content = "Berbagi hadiah adalah cara yang bagus untuk mempertahankan persahabatan yang berharga.",
  ui_story_5025_50253301_40_dialog_content = "Lihat ini. Buku catatan macam apa yang bakal temanmu sukai?",
  ui_story_5025_50253301_41_dialog_content = "Jenis apa?",
  ui_story_5025_50253301_42_dialog_content = "Hmm... Sekarang, Vice menggunakan buku catatan tebal bersampul cokelat.",
  ui_story_5025_50253301_43_dialog_content = "Saya tidak yakin mana yang cocok berdasarkan informasi terbatas yang Anda berikan.",
  ui_story_5025_50253301_44_dialog_content = "Di sini ada buku catatan, buku agenda, diari mingguan, buku jadwal spiral, dan buku perencanaan.",
  ui_story_5025_50253301_45_dialog_content = "Yang paling populer pasti jurnal ini yang memungkinkan Anda beralih halaman.",
  ui_story_5025_50253301_46_dialog_content = "Ada halaman yang bergaris biasa, yang ada kotak-kotaknya, yang polos, dan yang ada titik-titiknya.",
  ui_story_5025_50253301_47_dialog_content = "Ada juga halaman variasi campuran untuk memenuhi kebutuhan Anda yang berbeda untuk rencana mingguan, daftar tugas bulanan, dan pembukuan.",
  ui_story_5025_50253301_48_dialog_content = "Mereka juga dapat dipasangkan dengan berbagai tali pengikat, bookmark, stiker, dan sampul dengan warna berbeda untuk Anda pilih...",
  ui_story_5025_50253301_49_dialog_content = "Sebentar! Ini makin membingungkan.",
  ui_story_5025_50253301_50_dialog_content = "Saya pikir ... buku diary sederhana sudah cukup.",
  ui_story_5025_50253301_51_dialog_content = "Sayang, buku diary lama yang biasa sudah ketinggalan zaman.",
  ui_story_5025_50253301_52_dialog_content = "Apakah Anda mendapatkan hadiah yang membosankan untuk teman Anda yang paling berharga?",
  ui_story_5025_50253301_53_dialog_content = "Aku...",
  ui_story_5025_50253301_54_dialog_content = "Mendengarkan. Anda tidak perlu terburu-buru dan memutuskan sekarang.",
  ui_story_5025_50253301_55_dialog_content = "Cari tahu apa yang sebenarnya disukai teman Anda terlebih dahulu dan putuskan.",
  ui_story_5025_50253301_56_dialog_content = "Saya akan meminta petugas pengiriman membawakan Anda berbagai buku catatan untuk Anda pilih.",
  ui_story_5025_50253301_57_dialog_content = "Yang harus Anda lakukan adalah menanggung biaya pengiriman.",
  ui_story_5025_50253301_58_dialog_content = "Baiklah...",
  ui_story_5025_50253301_59_dialog_content = "Cari tahu apa Vice suka?",
  ui_story_5025_50253301_60_dialog_content = "Tadinya kukira aku cukup mengenalnya, tapi kenapa aku tak bisa memilih buku catatan yang cocok, sih?",
  ui_story_5025_50253301_61_dialog_content = "Mungkin aku harus...",
  ui_story_5025_50253301_62_dialog_content = "Tunggu... Jika aku pergi bertanya padanya, itu tidak akan menjadi kejutan lagi.",
  ui_story_5025_50253301_63_dialog_content = "Tunggu, mungkin Carleen tahu...",
  ui_story_5025_50253301_64_dialog_content = "Aku mengerti.",
  ui_story_5025_50253301_65_dialog_content = "Perhatian Anda atas tindakan yang tampaknya tidak penting ini benar-benar terpuji.",
  ui_story_5025_50253301_66_dialog_content = "Sejujurnya, aku juga belum pernah melihat buku catatannya.",
  ui_story_5025_50253301_67_dialog_content = "Tapi saya kira perencana jaringan atau buku jadwal akan tepat untuknya.",
  ui_story_5025_50253301_68_dialog_content = "Dia telah mengurus semuanya di Colossus. Ini akan sangat membantu.",
  ui_story_5025_50253301_69_dialog_content = "Pilihan Anda yang lain adalah... buku akun.",
  ui_story_5025_50253301_70_dialog_content = "Vice kan cukup rajin dan cermat dalam mengelola Colossus. Dia mungkin menyukai buku besar.",
  ui_story_5025_50253301_71_dialog_content = "Vice sangat rajin tapi saya ragu dia mengisi buku hariannya dengan rencana kerja.",
  ui_story_5025_50253301_72_dialog_content = "Jauh di dalam lubuk hatinya, dia adalah gadis kecil manis yang suka berjalan-jalan dan bertualang.",
  ui_story_5025_50253301_73_dialog_content = "Siapa tahu, mungkin buku hariannya dipenuhi stiker-stiker cantik.",
  ui_story_5025_50253301_74_dialog_content = "Maaf. Saya khawatir Anda bertanya kepada orang yang salah.",
  ui_story_5025_50253301_75_dialog_content = "Tapi saya membayangkan alasan dia menyukai sampul cokelat adalah karena cintanya pada Illumina...",
  ui_story_5025_50253301_76_dialog_content = "Coklat adalah warna bumi, sederhana dan mantap, sama seperti dia.",
  ui_story_5025_50253301_77_dialog_content = "Saya akan mengatakan biru langit juga cocok untuknya.",
  ui_story_5025_50253301_78_dialog_content = "Haha. Tak kusangka kau minta bantuan kami.",
  ui_story_5025_50253301_79_dialog_content = "Kami sudah menjual banyak barang kepadanya, termasuk sketsa dan gambarmu...",
  ui_story_5025_50253301_80_dialog_content = "Sebentar! Jangan marah kepada kami, dong... Kami punya informasi penting untukmu. Serius!",
  ui_story_5025_50253301_81_dialog_content = "Dia menambahkan gambarmu ke koleksinya. Kami lihat dia menaruhnya dengan hati-hati dalam buku catatannya.",
  ui_story_5025_50253301_82_dialog_content = "Buku catatan kosong cocok untuknya. Dia bisa menambahkan gambar dan stiker!",
  ui_story_5025_50253301_83_dialog_content = "Tidak, saya pikir itu akan lebih cocok untuk PlayerName.",
  ui_story_5025_50253301_84_dialog_content = "Kanan?",
  ui_story_5025_50253301_85_dialog_content = "Omong-omong, kebetulan kami punya buku sketsa kosong, nih. Ambillah, gambar apa pun yang kau suka...",
  ui_story_5025_50253301_86_dialog_content = "Apakah dia tidak suka memasak?",
  ui_story_5025_50253301_87_dialog_content = "Saya pikir dia melalui fase meneliti masakan kreatif.",
  ui_story_5025_50253301_88_dialog_content = "Saya mendengar dia bahkan membuat shake rumput laut hijau yang sehat.",
  ui_story_5025_50253301_89_dialog_content = "Nah, buku resep adalah barang penting untuk koki kreatif dan berbakat.",
  ui_story_5025_50253301_90_dialog_content = "Pokoknya, piwih saja yang kau suka untuk Vice.",
  ui_story_5025_50253301_91_dialog_content = "Kuwasa Vice bakaw menyukai apa pun yang kau suka.",
  ui_story_5025_50253301_92_dialog_content = "Lagipula, Vice dan kalian adalah teman baik. Heheh. Heheheh.",
  ui_story_5025_50253301_93_dialog_content = "Entah bagaimana saya akhirnya meminta begitu banyak orang... Semua orang sangat ingin membantu.",
  ui_story_5025_50253301_94_dialog_content = "Ketika saya memikirkannya, mereka semua membuat beberapa poin bagus.",
  ui_story_5025_50253301_95_dialog_content = "Dia memang suka melakukan pembukuan dan memasak. Dia orang yang tekun, bisa diandalkan, lembut, dan manis.",
  ui_story_5025_50253301_96_dialog_content = "Mungkin sebaiknya dia kubelikan buku jurnal dengan bermacam-macam jenis halaman.",
  ui_story_5025_50253301_97_dialog_content = "PlayerName, apa yang kamu gumamkan? Anda ingin membeli sesuatu?",
  ui_story_5025_50253301_98_dialog_content = "*Batuk* Tidak... Tidak sama sekali.",
  ui_story_5025_50253301_99_dialog_content = "TIDAK? Sangat mencurigakan... Apakah Anda mendapatkan semua yang ada di daftar?",
  ui_story_5025_50253301_100_dialog_content = "Ya. Sheol akan mengatur pengiriman sebentar lagi.",
  ui_story_5025_50253301_101_dialog_content = "Bagus sekali. Hubungi saya jika barang sudah sampai agar saya bisa melihatnya.",
  ui_story_5025_50253301_102_dialog_content = "Kalau-kalau kau membeli sesuatu yang seharusnya tak kau beli...",
  ui_story_5025_50253301_103_dialog_content = "Tidak perlu, saya berjanji kepada Anda bahwa saya tidak melakukan kesalahan.",
  ui_story_5025_50253301_104_dialog_content = "<size=30>Hmm... Dia sangat ketat kalau soal neraca keuangan... Mungkin sebaiknya kuberi dia buku besar saja...</size>",
  ui_story_5025_50253301_105_dialog_content = "Apa katamu? Saya pikir saya baru saja mendengar \"buku akun\" ...",
  ui_story_5025_50253301_106_dialog_content = "Aku hampir yakin kau menyembunyikan sesuatu dariku.",
  ui_story_5025_50253301_107_dialog_content = "Hah? Apa maksudmu?",
  ui_story_5025_50253301_108_dialog_content = "Hmm... Terserah, deh...",
  ui_story_5025_50253301_109_dialog_content = "Karena sudah lama menempuh perjalanan denganmu, aku jadi tahu kalau ada sesuatu yang kau pikirkan.",
  ui_story_5025_50253301_110_dialog_content = "Jika ada yang ingin kau katakan atau tanyakan, jangan ditahan.",
  ui_story_5025_50253301_111_dialog_content = "Aku...",
  ui_story_5025_50253301_112_option_content = "Sungguh?",
  ui_story_5025_50253301_113_dialog_content = "Iya! Ada apa?",
  ui_story_5025_50253301_114_dialog_content = "Opo opo...",
  ui_story_5025_50253301_115_dialog_content = "Mana yang lebih kau sukai? Pembukuan, membuat rencana, mempelajari resep, atau mengumpulkan gambar dan stiker?",
  ui_story_5025_50253301_116_dialog_content = "Err... Mengapa Anda bertanya?",
  ui_story_5025_50253301_117_dialog_content = "Tidak apa-apa jika Anda menyukai semuanya, tetapi saya ingin tahu apakah Anda memiliki preferensi!",
  ui_story_5025_50253301_118_dialog_content = "Eh... Aku jadi bingung.",
  ui_story_5025_50253301_119_dialog_content = "Saya pikir Anda akan mengaku tentang pembelian yang tidak perlu ...",
  ui_story_5025_50253301_120_option_content = "Aku benar-benar tidak menyembunyikan apapun.",
  ui_story_5025_50253301_121_dialog_content = "Lihatlah kejujuran di mataku.",
  ui_story_5025_50253301_122_dialog_content = "Bahkan jika saya melakukannya, itu akan menjadi sesuatu yang mutlak diperlukan!",
  ui_story_5025_50253301_123_dialog_content = "Jadi, kau memang...",
  ui_story_5025_50253301_124_dialog_content = "Pengiriman! Mendekut! Adakah yang bisa menandatanganinya?",
  ui_story_5025_50253301_125_dialog_content = "Ah! Dove rupanya. Sebelah sini!",
  ui_story_5025_50253301_126_dialog_content = "Huff, huff... Aku tidak menyangka satu buku harian kecil menjadi sebesar dan seberat ini...",
  ui_story_5025_50253301_127_dialog_content = "Jika saya tahu, saya tidak akan setuju untuk menyampaikan ini.",
  ui_story_5025_50253301_128_dialog_content = "Tunggu. Apakah Anda mengatakan buku harian?",
  ui_story_5025_50253301_129_dialog_content = "Iya. Halaman buku harianku yang lama kan sudah hampir habis.",
  ui_story_5025_50253301_130_dialog_content = "Jenis notebook ekstra besar ini hanya dapat ditukar menggunakan kupon Illumina. saya bertanya Dove untuk membantu membawa satu.",
  ui_story_5025_50253301_131_dialog_content = "Terima kasih, Dove. Akan kutraktir kau makan malam.",
  ui_story_5025_50253301_132_dialog_content = "Selama Anda tidak memasak, coo ...",
  ui_story_5025_50253301_133_dialog_content = "Hei! Aku ini koki yang andal, tahu?",
  ui_story_5025_50253301_134_dialog_content = "<size=30>Dia sudah punya buku catatan baru...</size>",
  ui_story_5025_50253301_135_dialog_content = "<size=30>Maka yang ingin saya beli tidak akan banyak berguna ...</size>",
  ui_story_5025_50253301_136_dialog_content = "Hah? PlayerName, kau bilang sesuatu?",
  ui_story_5025_50253301_137_dialog_content = "Ah... Maaf, permisi sebentar.",
  ui_story_5025_50253301_138_dialog_content = "Orang pengiriman akan datang, saya perlu berbicara dengan mereka dengan cepat ...",
  ui_story_5025_50253301_139_dialog_content = "Argh! Banyak sekali yang harus diantar. Aku lelah.",
  ui_story_5025_50253301_140_dialog_content = "Bayarannya lebih baik kali ini... Apakah kita mendapatkan jumlah yang layak? Seperti nyata?",
  ui_story_5025_50253301_141_dialog_content = "Terima kasih sudah memilih Courier Union.",
  ui_story_5025_50253301_142_dialog_content = "Heheh. Layananmu akan dibayar oleh klienku yang murah hati. Mungkin sebaiknya kau berterima kasih kepadanya.",
  ui_story_5025_50253301_143_dialog_content = "Sheol, senang bertemu denganmu. Begini...",
  ui_story_5025_50253301_144_dialog_content = "Buku catatannya... Aku sudah tak butuh lagi. Vice sudah membelinya sendiri.",
  ui_story_5025_50253301_145_dialog_content = "Tidak membutuhkannya lagi? Apa kau mengembalikan ini?!",
  ui_story_5025_50253301_149_dialog_content = "Mengapa Anda menyerah untuk memberinya hadiah ini?",
  ui_story_5025_50253301_150_dialog_content = "Walaupun dia sudah beli yang baru, kau kan tetap bisa membelikannya hadiah.",
  ui_story_5025_50253301_151_dialog_content = "Hadiah itu mewakili niat Anda. Ini tentang upaya Anda untuk membuatnya bahagia.",
  ui_story_5025_50253301_152_dialog_content = "Ketika Anda berjuang untuk memilih hadiah yang cocok untuknya, saya merasakan betapa Anda sangat peduli padanya.",
  ui_story_5025_50253301_153_dialog_content = "Aku yakin dia juga akan merasakannya.",
  ui_story_5025_50253301_154_dialog_content = "Hmm, aku tahu... Sebenarnya aku sudah memutuskan.",
  ui_story_5025_50253301_155_dialog_content = "Oh? Dan saya pikir ini akan membuat Anda kesal. Tapi kamu terlihat baik-baik saja.",
  ui_story_5025_50253301_155X1_dialog_content = "Sebenarnya, aku memang agak sedih...",
  ui_story_5025_50253301_155X2_dialog_content = "Saya berharap saya baru saja mengatakan kepadanya secara langsung bahwa saya berencana membelikannya buku harian baru.",
  ui_story_5025_50253301_156_dialog_content = "Jadi... Sekarang, apa rencanamu?",
  ui_story_5025_50253301_157_dialog_content = "Hmm... Aku akan membeli satu buku besar, satu buku perencanaan, satu buku sketsa, dan satu buku jadwal!",
  ui_story_5025_50253301_158_dialog_content = "Lagipula, beberapa buku catatan tidak akan merusak bank. Mereka semua akan digunakan cepat atau lambat.",
  ui_story_5025_50253301_159_dialog_content = "Saya akan memberinya beberapa sehingga dia bisa menggunakan mana yang dia suka kapan pun dia mau.",
  ui_story_5025_50253301_160_dialog_content = "Haha. Kau memang klien yang sangat murah hati!",
  ui_story_5025_50253301_161_dialog_content = "Fyuh... Akhirnya...",
  ui_story_5025_50253301_162_dialog_content = "Seharusnya begini saja sejak awal... Aku memang bodoh.",
  ui_story_5025_50253301_163_dialog_content = "Aku tinggal mencari cara untuk memberikan setumpuk buku catatan ini...",
  ui_story_5025_50253301_164_dialog_content = "Vice... Hmm? Dia pergi ke mana, ya?",
  ui_story_5025_50253301_165_dialog_content = "<color=#e8d9bb>Dor!</color>",
  ui_story_5025_50253301_166_dialog_content = "Dari mana datangnya pita dan kerupuk kertas ini?",
  ui_story_5025_50253301_167_dialog_content = "Ini adalah hadiah kecil dari Rediesel Wrench. Saya pikir mereka akan sempurna untuk acara khusus ...",
  ui_story_5025_50253301_168_dialog_content = "Benar, Anda baru saja mengatakan kurir datang. Semua yang Anda beli dikirim?",
  ui_story_5025_50253301_169_dialog_content = "Ya, semuanya sudah beres... Tapi acara spesial apa hari ini?",
  ui_story_5025_50253301_170_dialog_content = "Jangan bilang Anda merayakan perjalanan belanja saya yang sukses...",
  ui_story_5025_50253301_170X_dialog_content = "Ah-ha-ha. Jika kita harus punya alasan untuk merayakannya, bagaimana dengan penyelesaian jurnal perjalanan dan petualangan saya?",
  ui_story_5025_50253301_171_dialog_content = "Hmm? Agak serampangan, ya?",
  ui_story_5025_50253301_172_dialog_content = "Hmm... Anu... Bagaimana cara mengatakannya, ya?",
  ui_story_5025_50253301_173_dialog_content = "Aku sadar halaman buku harianku sudah hampir habis.",
  ui_story_5025_50253301_174_dialog_content = "Jadi, kuputuskan untuk mengakhirinya dengan sesuatu yang spesial...",
  ui_story_5025_50253301_175_dialog_content = "Aku sudah memikirkannya matang-matang...",
  ui_story_5025_50253301_176_dialog_content = "Saya mulai membuat jurnal ini setelah kami bertemu.",
  ui_story_5025_50253301_177_dialog_content = "Nama Anda lebih sering muncul di buku daripada nama orang lain.",
  ui_story_5025_50253301_178_dialog_content = "Karena saya memulai buku harian ini untuk mencatat hal-hal tentang Anda, masuk akal untuk menyelesaikannya dengan sesuatu tentang Anda.",
  ui_story_5025_50253301_178X_dialog_content = "Lalu, aku memutuskan untuk melakukan sesuatu sebagai ucapan terima kasih atas perjalanan yang sangat spesial ini.",
  ui_story_5025_50253301_179_dialog_content = "Singkatnya, kujadikan hari ini hari spesial untukmu dan aku akan mencatatnya sebagai entri terakhir di jurnalku!",
  ui_story_5025_50253301_180_dialog_content = "Eh... Baiklah. Sepertinya aku paham sekarang...",
  ui_story_5025_50253301_180X_dialog_content = "Lalu, kita harus bagaimana? Kita rayakan dengan apa, nih?",
  ui_story_5025_50253301_181_dialog_content = "Hari ini kau tak akan diomeli karena sudah membelanjakan banyak uang.",
  ui_story_5025_50253301_182_dialog_content = "Tadinya aku sudah merencanakan pesta untukmu, tapi...",
  ui_story_5025_50253301_183_dialog_content = "Pesta?!",
  ui_story_5025_50253301_184_dialog_content = "Ada apa dengan ekspresi ketakutan di wajahmu itu?",
  ui_story_5025_50253301_185_dialog_content = "Saya ingin membuktikan bahwa saya benar-benar bisa memasak. Apa yang salah dengan itu?",
  ui_story_5025_50253301_186_dialog_content = "Tidak ada... Tidak ada yang salah... Ini baik-baik saja.",
  ui_story_5025_50253301_187_dialog_content = "Omong-omong, aku sudah berubah pikiran karena mendapat ide yang lebih bagus!",
  ui_story_5025_50253301_188_dialog_content = "Apa itu?",
  ui_story_5025_50253301_189_dialog_content = "Akan kuminta semua orang untuk menulis pesan untukmu!",
  ui_story_5025_50253301_191_dialog_content = "Pesan untukku?",
  ui_story_5025_50253301_192_dialog_content = "Ya, semua tentangmu...",
  ui_story_5025_50253301_193_dialog_content = "Heheh. Anda dan PlayerName adalah pasangan yang lucu. Dia baru datang belum lama ini...",
  ui_story_5025_50253301_194_dialog_content = "Adapun alasannya... Aku belum bisa memberitahumu.",
  ui_story_5025_50253301_195_dialog_content = "Yang bisa saya katakan adalah... Kepedulian dan pertimbangan yang Anda miliki terhadap satu sama lain tampaknya bagus.",
  ui_story_5025_50253301_196_dialog_content = "Iya, aku setuju.",
  ui_story_5025_50253301_197_dialog_content = "Jadi tentang pesannya... Bisakah saya menulis sesuatu yang sederhana saja? Menyukai...",
  ui_story_5025_50253301_198_dialog_content = "\"Terima kasih atas bantuanmu, PlayerName.\"",
  ui_story_5025_50253301_199_dialog_content = "Anak saya. Aku juga ingin menulis sesuatu!",
  ui_story_5025_50253301_200_dialog_content = "Aku mau biwang bahwa bewmain dengan PlayerName sangat menyenangkan.",
  ui_story_5025_50253301_201_dialog_content = "Kuhawap Gwammy dan Sanki bisa tuwut bewgabung wain kawi!",
  ui_story_5025_50253301_201X_dialog_content = "Iya, pasti menyenangkan.",
  ui_story_5025_50253301_202_dialog_content = "Sebuah pesan untuk PlayerName?",
  ui_story_5025_50253301_203_dialog_content = "Hmm... \"Kedatanganmu untuk memperkuat stasiun transportasi kami pada hari itu sangat membantu.\"",
  ui_story_5025_50253301_203X_dialog_content = "\"Kau memang komandan yang hebat.\"",
  ui_story_5025_50253301_204_dialog_content = "Kalian sedang apa, sih? Ada yang bilang \"komandan\"?",
  ui_story_5025_50253301_205_dialog_content = "Kami meninggalkan pesan untuk PlayerName. Datang dan tulis sesuatu.",
  ui_story_5025_50253301_206_dialog_content = "Aku tak paham. Memangnya apa yang harus aku tulis?",
  ui_story_5025_50253301_207_dialog_content = "Anda bisa berterima kasih PlayerName atau sesuatu.",
  ui_story_5025_50253301_208_dialog_content = "Baiklah…",
  ui_story_5025_50253301_209_dialog_content = "\"Kau boleh berterima kasih kepada PlayerName\"... Sudah.",
  ui_story_5025_50253301_210_dialog_content = "Aku ingin berterima kasih kepada PlayerName... dan semua orang.",
  ui_story_5025_50253301_211_dialog_content = "Saya tidak akan pernah melupakan perjalanan kita ke laut.",
  ui_story_5025_50253301_212_dialog_content = "Dan... aku baru saja menerima balasan dari Paloma. Kali ini, dia cepat sekali membalasnya.",
  ui_story_5025_50253301_213_dialog_content = "Dia bilang... \"Tak kusangka kau bakal menghubungiku untuk urusan sepele semacam ini.\"",
  ui_story_5025_50253301_214_dialog_content = "\"Tapi kalau untuk Navigator, aku akan melakukannya.\"",
  ui_story_5025_50253301_215_dialog_content = "\"Dia pria yang sangat baik. Tolong tinggalkan pesan itu untukku.\"",
  ui_story_5025_50253301_216_dialog_content = "Beberapa pesan sih tidak seberapa!",
  ui_story_5025_50253301_217_dialog_content = "Sebaiknya bawa dia ke sini agar bisa makan-makan dengan Rediesel Wrench!",
  ui_story_5025_50253301_218_dialog_content = "Kak! Maksudmu, sebaiknya kita mengundangnya?",
  ui_story_5025_50253301_219_dialog_content = "Benar. Eve benar.",
  ui_story_5025_50253301_220_dialog_content = "Oh, iya. Bicara soal Eve, aku sangat berterima kasih kepadanya.",
  ui_story_5025_50253301_221_dialog_content = "Navigator boleh bergabung dengan Rediesel Wrench kapan saja. Aku yakin dia muak dengan baris ini.",
  ui_story_5025_50253301_222_dialog_content = "Biar kuulangi. Rediesel Wrench akan selalu berpihak pada PlayerName!",
  ui_story_5025_50253301_223_dialog_content = "Tsk... Kedengarannya juga tidak bagus. aku perlu berpikir...",
  ui_story_5025_50253301_224_dialog_content = "Akan kuminta semua anggota Rediesel Wrench di sini untuk menuliskan sesuatu. Roy pasti bakal menyukainya...",
  ui_story_5025_50253301_225_dialog_content = "Tapi, sepertinya halaman bukumu tak cukup...",
  ui_story_5025_50253301_226_dialog_content = "\"Kepada PlayerName: Kau adalah tamu kehormatan Guild sekaligus teman baikku.\"",
  ui_story_5025_50253301_227_dialog_content = "\"Akan selalu kuingat bantuanmu kepada kami dan kebaikan hatimu.\"",
  ui_story_5025_50253301_228_dialog_content = "Dan keberanian PlayerName.",
  ui_story_5025_50253301_229_dialog_content = "Dia selalu menyerbu ke depan untuk melibatkan Eclipsites itu dan melindungi kita semua.",
  ui_story_5025_50253301_230_dialog_content = "Banyak sekali yang ingin kukatakan. Bagaimana cara menuliskannya dengan singkat, ya?",
  ui_story_5025_50253301_231_dialog_content = "Hmm... Yang paling penting saja?",
  ui_story_5025_50253301_232_dialog_content = "Baiklah... Bagaimana kalau begini? \"Aku ingin merayakan Tahun Baru denganmu lagi!\"",
  ui_story_5025_50253301_233_dialog_content = "Yang Mulia Ratu dan Novio pasti akan setuju denganku.",
  ui_story_5025_50253301_234_dialog_content = "... Mereka semua punya banyak hal untuk diceritakan PlayerName.",
  ui_story_5025_50253301_235_dialog_content = "Memang. Kami sebenarnya menerima lebih banyak balasan.",
  ui_story_5025_50253301_235X1_dialog_content = "Dalam suratnya, Hedy bertanya apa dia boleh membelikan PlayerName rumah.",
  ui_story_5025_50253301_235X2_dialog_content = "Ah... Ini...",
  ui_story_5025_50253301_235X3_dialog_content = "Saya menolak tawaran itu.",
  ui_story_5025_50253301_235X4_dialog_content = "Ahaha! Itu sangat disayangkan...",
  ui_story_5025_50253301_235X5_dialog_content = "Kalau begitu, sisa halaman di buku harianmu jelas tidak cukup.",
  ui_story_5025_50253301_236_dialog_content = "Ya... Saya kira saya perlu buku catatan yang lebih besar lain kali.",
  ui_story_5025_50253301_237_dialog_content = "Kau menyisihkan satu baris untuk PlayerName?",
  ui_story_5025_50253301_238_dialog_content = "Tentu saja. Kata-kata terakhir harus berasal dari PlayerName sendiri. Eh, kau belum menulis apa-apa, lho.",
  ui_story_5025_50253301_239_dialog_content = "Aku? Ehem... Kita kan sudah lama sekali bersama. Itu tak begitu penting...",
  ui_story_5025_50253301_240_dialog_content = "Itu perlu! Ini sangat diperlukan! Ini kesempatan Anda untuk menumpahkan isi hati Anda.",
  ui_story_5025_50253301_241_dialog_content = "Karena kita sudah bersama begitu lama, penting bagi kita untuk mengungkapkan perasaan kita.",
  ui_story_5025_50253301_242_dialog_content = "Baik, Anda ada benarnya. Kemudian...",
  ui_story_5025_50253301_243_dialog_content = [[
"Terima kasih telah menjadi bagian dari hidupku."
"Masa depan masih panjang dan kita masih punya banyak waktu..."
]],
  ui_story_5025_50253301_244_dialog_content = "\"Ayo teruskan perjalanan kita. —Dari Carleen\"",
  ui_story_5025_50253301_245_dialog_content = "Nah, ini yang benar-benar ingin Carleen katakan.",
  ui_story_5025_50253301_246_dialog_content = "Ini yang membuat kalian sibuk belakangan ini...",
  ui_story_5025_50253301_247_dialog_content = "Iya. Awalnya, aku meminta teman-teman kita di Colossus menulis pesan untukmu.",
  ui_story_5025_50253301_248_dialog_content = "Tetapi semakin banyak orang akhirnya mengambil bagian.",
  ui_story_5025_50253301_249_dialog_content = "Bagaimana menurutmu? Kau ingat kejadian-kejadian yang mereka sebutkan?",
  ui_story_5025_50253301_250_option_content = "Hmm... Hanya beberapa, sih.",
  ui_story_5025_50253301_251_dialog_content = "Sebentar, biar aku ingat-ingat dulu...",
  ui_story_5025_50253301_252_dialog_content = "Kalau kau tak ingat juga tidak apa-apa. Lanjutkan saja.",
  ui_story_5025_50253301_253_dialog_content = "Kenangan di masa lalu akan kembali saat bertemu lagi dengan teman-teman kita.",
  ui_story_5025_50253301_254_option_content = "Tentu saja. Aku ingat mereka semua, kok.",
  ui_story_5025_50253301_255_dialog_content = "Sejak aku kembali ke dunia dari bawah tanah dan memulai perjalanan ini...",
  ui_story_5025_50253301_256_dialog_content = "Kami telah mengalami begitu banyak dan bertemu begitu banyak orang. Itu semua adalah kenangan berharga.",
  ui_story_5025_50253301_257_dialog_content = "Benar. Ada lebih banyak petualangan dan orang menarik yang menunggu kita.",
  ui_story_5025_50253301_258_dialog_content = "Kami akan terus melakukan perjalanan bersama!",
  ui_story_5025_50253301_258X_dialog_content = "Itu sebabnya saya beralih ke notebook yang lebih tebal.",
  ui_story_5025_50253301_259_dialog_content = "Ha ha. Aku merasa sedikit emosional...",
  ui_story_5025_50253301_260_dialog_content = "Aku sangat bahagia. Dan saya mengingat begitu banyak kenangan lama!",
  ui_story_5025_50253301_261_dialog_content = "Sayangnya, notebook saya tidak cukup besar untuk mencatat semuanya...",
  ui_story_5025_50253301_262_dialog_content = "Saya akan membiarkan Anda melihatnya setelah saya mengatur semuanya.",
  ui_story_5025_50253301_263_dialog_content = "Haha. Terima kasih. Aku jadi tak sabar!",
  ui_story_5025_50253301_264_dialog_content = "Oh, iya. Bicara soal buku catatan... Aku punya sekotak besar untukmu.",
  ui_story_5025_50253301_265_dialog_content = "Dari perencana hingga buku jadwal, dari buku akun hingga buku sketsa, ditambah setumpuk kertas lepas dan pembatas buku...",
  ui_story_5025_50253301_266_dialog_content = "Aku punya segalanya tertutup. Tidak usah buru-buru. Jangan terburu-buru.",
  ui_story_5025_50253301_267_dialog_content = "...",
  ui_story_5025_50253301_268_dialog_content = "Halo? Kau baik-baik saja?",
  ui_story_5025_50253301_269_dialog_content = "Heheh. Aku tidak apa-apa, kok... Ini kejutan yang menyenangkan! Aku sangat gembira!",
  ui_story_5025_50253301_270_dialog_content = "Aku merasa pikiran kita sinkron...",
  ui_story_5025_50253301_271_dialog_content = "Tambahan pengeluaran itu rupanya untuk membelikanku hadiah. Aku hampir salah paham padamu. Maafkan aku.",
  ui_story_5025_50253301_272_dialog_content = "Haha. Aku berusaha keras untuk memberi penjelasan tanpa membocorkan kejutannya.",
  ui_story_5025_50253301_273_dialog_content = "Saya tahu Anda selalu berjuang untuk menjaga pengeluaran kami di Colossus sesuai anggaran.",
  ui_story_5025_50253301_274_dialog_content = "Saya kadang-kadang menghabiskan uang. Saya menghargai Anda meminta pertanggungjawaban saya.",
  ui_story_5025_50253301_275_dialog_content = "Heheh. Sepertinya saya punya satu hal bagus lagi untuk ditambahkan ke entri buku harian hari ini.",
  ui_story_5025_50253301_276_dialog_content = "Sebentar. Apa pesanmu untukku?",
  ui_story_5025_50253301_277_dialog_content = "Aku tak melihat \"apa yang paling ingin Vice katakan kepada PlayerName\" di mana pun, tuh.",
  ui_story_5025_50253301_278_dialog_content = "Hmm? Kau kan sudah membawa buku harianku. Kau tidak paham, ya?",
  ui_story_5025_50253301_279_dialog_content = "Isi buku harian inilah yang aku ingin kau tahu.",
  ui_story_5025_50253301_280_dialog_content = "Ambillah, dan bacalah di waktu Anda sendiri.",
  ui_story_5025_50253301_281_dialog_content = "I-Ini untukku?",
  ui_story_5025_50253301_282_dialog_content = "Iya, jangan dikembalikan!",
  ui_story_5025_50253301_283_dialog_content = "Satu hal lagi. Saya ingin Anda menulis baris terakhir di buku harian ini...",
  ui_story_5025_50253301_284_dialog_content = "Aku?",
  ui_story_5025_50253301_285_dialog_content = "Iya! Lagi pula, buku harian ini kan tentang dirimu!",
  ui_story_5025_50253301_286_dialog_content = "Saya ingin Anda menyelesaikannya.",
  ui_story_5025_50253301_287_dialog_content = "Melihat kembali perjalanan kita, apa yang ingin Anda katakan?",
  ui_story_5025_50253301_288_dialog_content = "Luangkan waktu Anda ... Pikirkan tentang itu dan tulislah saat Anda siap.",
  ui_story_5025_50253301_289_dialog_content = "aku akan selalu disini menunggumu..."
}
return config
